import{_ as t,a as r,o as i,a4 as s}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Delete Subscriber","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete","title":"Delete Subscriber","description":"Delete a newsletter subscriber by id. A successful delete returns no errors; the subscriber is removed.","query":"mutation DeleteAdminMarketingSubscriber(\\n  $input: deleteAdminMarketingSubscriberInput!\\n) {\\n  deleteAdminMarketingSubscriber(input: $input) {\\n    adminMarketingSubscriber {\\n      _id\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/marketing/subscribers/26\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminMarketingSubscriber\\": {\\n      \\"adminMarketingSubscriber\\": null\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/subscribers-delete.md","filePath":"api/graphql-api/admin/marketing/communications/subscribers-delete.md","lastUpdated":1783420618000}'),a={name:"api/graphql-api/admin/marketing/communications/subscribers-delete.md"};function n(d,e,o,c,l,b){return i(),r("div",null,e[0]||(e[0]=[s('<h1 id="delete-subscriber" tabindex="-1">Delete Subscriber <a class="header-anchor" href="#delete-subscriber" aria-label="Permalink to &quot;Delete Subscriber&quot;">​</a></h1><p>Deletes a newsletter subscriber — the <strong>Delete</strong> row action on the admin <strong>Marketing → Communications → Newsletter Subscribers</strong> screen. When the subscriber is linked to a registered customer, that customer is unsubscribed before the row is removed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/communications/subscribers/">Newsletter Subscribers overview</a> for what a subscriber is and how its fields behave.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminMarketingSubscriber</code></td><td>Mutation</td><td>Delete a newsletter subscriber</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.communications.subscribers.delete</code> permission.</li><li>Pass the subscriber&#39;s IRI as <code>id</code>. Use the <a href="/api/graphql-api/admin/marketing/communications/subscribers-list.html">list</a> query to discover valid ids.</li></ul><div class="warning custom-block"><p class="custom-block-title">Confirm success via the absence of <code>errors</code></p><p>The delete mutation returns a success acknowledgement, not the deleted subscriber&#39;s data — <code>adminMarketingSubscriber</code> resolves to <code>null</code> on the payload. <strong>Treat a response with no <code>errors[]</code> as a successful delete.</strong> If you need a confirmation message in the body, use the REST endpoint (<code>DELETE /api/admin/marketing/subscribers/{id}</code>), which returns <code>{ &quot;message&quot;: &quot;Subscriber deleted.&quot; }</code>.</p></div><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>Yes</td><td>The subscriber&#39;s IRI</td></tr></tbody></table>',10)]))}const m=t(a,[["render",n]]);export{h as __pageData,m as default};
